+            var bajo = cu is >= 0xDC00 and <= 0xDFFF;
+            if (altoPendiente && !bajo) return true;
+            if (bajo && !altoPendiente) return true;
+            altoPendiente = alto;
+            i += 5;
+        }
+        else
+        {
+            if (altoPendiente) return true;
+            i++; // otro escape (\n, \\, \"): salta el carácter escapado
+        }
+    }
+    return altoPendiente;
+}
