content.content:
1	using System.Text.RegularExpressions;
2	
3	namespace TutorFlow.Api.Llm;
4	
5	public record Proveedor(string Nombre, ILlmClient Cliente, Precios Precios);
6	
7	// Principal primero; después los respaldos ordenados por su número. Nunca se mezclan dentro de una conversación.
8	public class Proveedores(IReadOnlyList<Proveedor> lista)
9	{
10	    public const string NombrePrincipal = "principal";
11	    static readonly Regex Patron = new(@"^LLM_RESPALDO_(\d+)_", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
12	
13	    public IReadOnlyList<Proveedor> Lista => lista;
14	
15	    public static ILlmClient CrearCliente(IHttpClientFactory fabrica, IConfiguration cfg, string prefijo)
16	    {
17	        var proveedor = (cfg[prefijo + "PROVIDER"] ?? "").Trim();
18	        if (proveedor.Length == 0 || proveedor.Equals("openai", StringComparison.OrdinalIgnoreCase))
19	            return new OpenAiCompatClient(fabrica, cfg, prefijo);
20	        if (proveedor.Equals("anthropic", StringComparison.OrdinalIgnoreCase))
21	            return new AnthropicClient(fabrica, cfg, prefijo);
22	        throw new InvalidOperationException($"{prefijo}PROVIDER no es válido: use 'openai' o 'anthropic'.");
23	    }
24	
25	    public static Proveedores Desde(IServiceProvider sp)
26	    {
27	        var cfg = sp.GetRequiredService<IConfiguration>();
28	        var lista = new List<Proveedor> { new(NombrePrincipal, sp.GetRequiredService<ILlmClient>(), sp.GetRequiredService<Precios>()) };
29	        var fabrica = sp.GetRequiredService<IHttpClientFactory>();
30	        var numeros = cfg.AsEnumerable()
31	            .Select(kv => Patron.Match(kv.Key))
32	            .Where(m => m.Success)
